46	// snapshotExportGraph deep-copies the graph so a read-only export can be
47	// checked against the exact prior state, lists included. Nil and empty lists
48	// are kept distinct, matching how Register stores them.
49	func snapshotExportGraph(graph map[string]*Lineage) map[string]*Lineage {
50		copyList := func(in []string) []string {
