1008	// Regression for a multi-path merge where comparing the full explanation path
1009	// and comparing only the merge node's direct upstream name give different
1010	// answers. source feeds a and b; a feeds z; b feeds c; report depends on z and
1011	// c together (c declared ahead of z on purpose); view depends on report. From
1012	// source both source->a->z->report and source->b->c->report have length 3. A
1013	// rule that only compares the final upstream would wrongly prefer the c route
1014	// (c < z); the full-path rule must compare from the origin and pick the a
1015	// route, because the paths first differ at hop 1 where a < b. view inherits
1016	// that explanation one hop further on.
1017	func TestImpactsMergedBranchesFullPathTieBreak(t *testing.T) {
1018		// Each sequence builds the same graph with a legal but different
1019		// registration order; the second also flips report's upstream list, and the
1020		// third registers the isolated node early. Names, distances and paths must
1021		// come out identical regardless.
1022		sequences := [][][]string{
1023			{
1024				{"source"},
1025				{"b", "source"}, // b-side branch registered first
1026				{"a", "source"},
1027				{"c", "b"},
1028				{"z", "a"},
1029				{"report", "c", "z"}, // c listed ahead of z on purpose
1030				{"view", "report"},
1031				{"isolated"},
1032			},
1033			{
1034				{"source"},
1035				{"a", "source"}, // opposite branch registered first
1036				{"z", "a"},
1037				{"b", "source"},
1038				{"c", "b"},
1039				{"report", "z", "c"}, // direct-upstream order flipped
1040				{"view", "report"},
1041				{"isolated"},
1042			},
1043			{
1044				{"source"},
1045				{"isolated"},
1046				{"b", "source"},
1047				{"a", "source"},
1048				{"z", "a"},
1049				{"c", "b"},
1050				{"report", "c", "z"},
1051				{"view", "report"},
1052			},
1053		}
1054	
1055		want := []Impact{
1056			{Dataset: "a", Distance: 1, Path: []string{"source", "a"}},
1057			{Dataset: "b", Distance: 1, Path: []string{"source", "b"}},
1058			{Dataset: "c", Distance: 2, Path: []string{"source", "b", "c"}},
1059			{Dataset: "z", Distance: 2, Path: []string{"source", "a", "z"}},
1060			{Dataset: "report", Distance: 3, Path: []string{"source", "a", "z", "report"}},
1061			{Dataset: "view", Distance: 4, Path: []string{"source", "a", "z", "report", "view"}},
1062		}
1063	
1064		for i, seq := range sequences {
1065			graph := buildRegisteredGraph(t, seq)
1066			assertConsistent(t, graph)
1067			before := snapshot(graph)
1068	
1069			impacts := mustImpacts(t, graph, "source")
1070			if !reflect.DeepEqual(impacts, want) {
1071				t.Fatalf("sequence %d: impacts = %v, want %v", i, impacts, want)
1072			}
1073	
1074			// Anchors with explicit messages: the merge node is explained exactly
1075			// once through a/z even though c sorts ahead of z, and view continues
1076			// along that same route.
1077			assertImpactOnce(t, impacts, "report", 3, []string{"source", "a", "z", "report"})
1078			assertImpactOnce(t, impacts, "view", 4, []string{"source", "a", "z", "report", "view"})
1079	
1080			// The origin itself and an unconnected dataset never appear.
1081			if names := impactNames(impacts); slices.Contains(names, "source") || slices.Contains(names, "isolated") {
1082				t.Fatalf("sequence %d: origin or isolated dataset leaked into %v", i, names)
1083			}
1084	
1085			// The query changes no node, relationship or stored list order.
1086			if !reflect.DeepEqual(snapshot(graph), before) {
1087				t.Fatalf("sequence %d: query changed graph: before=%v after=%v", i, before, snapshot(graph))
1088			}
1089		}
1090	}
1091	
1092	// With a direct source->report edge added on top of the merge scenario, edge
1093	// count takes priority over lexicographic order: report shortens to distance 1
1094	// and view to 2, both via the new edge, and the lexicographically smaller
1095	// length-3 route through a must not survive. The a/z and b/c branches remain
1096	// reachable on their own. The new upstream's position in report's declared
1097	// list must not change the result.
1098	func TestImpactsMergedBranchesDirectEdgeShortensMerge(t *testing.T) {
1099		// Two builds with opposite registration and upstream-list orders; the
1100		// direct edge is inserted at a different position in each.
1101		builds := []struct {
1102			registrations [][]string
1103			newParents    []string
1104		}{
1105			{
1106				registrations: [][]string{
1107					{"source"},
1108					{"b", "source"},
1109					{"a", "source"},
1110					{"c", "b"},
1111					{"z", "a"},
1112					{"report", "c", "z"},
1113					{"view", "report"},
1114					{"isolated"},
1115				},
1116				newParents: []string{"source", "c", "z"}, // direct edge first
1117			},
1118			{
1119				registrations: [][]string{
1120					{"source"},
1121					{"a", "source"},
1122					{"z", "a"},
1123					{"b", "source"},
1124					{"c", "b"},
1125					{"report", "z", "c"},
1126					{"view", "report"},
1127					{"isolated"},
1128				},
1129				newParents: []string{"c", "z", "source"}, // direct edge last
1130			},
1131		}
1132	
1133		want := []Impact{
1134			{Dataset: "a", Distance: 1, Path: []string{"source", "a"}},
1135			{Dataset: "b", Distance: 1, Path: []string{"source", "b"}},
1136			{Dataset: "report", Distance: 1, Path: []string{"source", "report"}},
1137			{Dataset: "c", Distance: 2, Path: []string{"source", "b", "c"}},
1138			{Dataset: "view", Distance: 2, Path: []string{"source", "report", "view"}},
1139			{Dataset: "z", Distance: 2, Path: []string{"source", "a", "z"}},
1140		}
1141	
1142		for i, build := range builds {
1143			graph := buildRegisteredGraph(t, build.registrations)
1144			mustRegister(t, graph, "report", build.newParents...)
1145			assertConsistent(t, graph)
1146			before := snapshot(graph)
1147	
1148			impacts := mustImpacts(t, graph, "source")
1149			if !reflect.DeepEqual(impacts, want) {
1150				t.Fatalf("build %d: impacts = %v, want %v", i, impacts, want)
1151			}
1152	
1153			// The short route wins even though the old a-route is lexicographically
1154			// smaller than any other length-3 explanation; both appear once.
1155			assertImpactOnce(t, impacts, "report", 1, []string{"source", "report"})
1156			assertImpactOnce(t, impacts, "view", 2, []string{"source", "report", "view"})
1157	
1158			// Both merged branches are still listed as affected datasets.
1159			assertImpact(t, impacts, "z", 2, []string{"source", "a", "z"})
1160			assertImpact(t, impacts, "c", 2, []string{"source", "b", "c"})
1161	
1162			if names := impactNames(impacts); slices.Contains(names, "source") || slices.Contains(names, "isolated") {
1163				t.Fatalf("build %d: origin or isolated dataset leaked into %v", i, names)
1164			}
1165			if !reflect.DeepEqual(snapshot(graph), before) {
1166				t.Fatalf("build %d: query changed graph: before=%v after=%v", i, before, snapshot(graph))
1167			}
1168		}
1169	}
