1186		// Unknown upstream: the error names the missing dataset.
1187		err := Register(graph, Dataset{Name: "mid"}, []string{"newsrc", "ghost"})
1188		if err == nil || !strings.Contains(err.Error(), "ghost") {
1189			t.Fatalf("want unknown-parent error naming ghost, got %v", err)
