1199			t.Fatalf("rejected re-wires changed graph: before=%v after=%v", before, snapshot(graph))
1200		}
1201		if got := mustImpacts(t, graph, "raw"); !reflect.DeepEqual(got, rawBefore) {
1202			t.Fatalf("raw impacts changed after rejected re-wires: got %v, want %v", got, rawBefore)
1203		}
