1276	// The provenance counterpart of the downstream merge scenario: source feeds a
1277	// and b; a feeds z; b feeds c; report depends on z and c together. Querying
1278	// report walks the parent edges, so source appears once at distance 3. Both
1279	// source->a->z->report and source->b->c->report have length 3; a rule that
1280	// only compares report's direct upstreams would wrongly prefer the c route
1281	// (c < z), but the full-path rule compares from the upstream onward and picks
1282	// the a route, because the paths first differ at hop 1 where a < b.
1283	func TestUpstreamsMergedBranchesFullPathTieBreak(t *testing.T) {
1284		// Each sequence builds the same graph with a legal but different
1285		// registration order; the second also flips report's upstream list. Names,
1286		// distances and paths must come out identical regardless.
1287		sequences := [][][]string{
1288			{
1289				{"source"},
1290				{"b", "source"}, // b-side branch registered first
1291				{"a", "source"},
1292				{"c", "b"},
1293				{"z", "a"},
1294				{"report", "c", "z"}, // c listed ahead of z on purpose
1295				{"view", "report"},
1296				{"isolated"},
1297			},
1298			{
1299				{"source"},
1300				{"a", "source"}, // opposite branch registered first
1301				{"z", "a"},
1302				{"b", "source"},
1303				{"c", "b"},
1304				{"report", "z", "c"}, // direct-upstream order flipped
1305				{"view", "report"},
1306				{"isolated"},
1307			},
1308		}
1309	
1310		want := []Upstream{
1311			{Dataset: "c", Distance: 1, Path: []string{"c", "report"}},
1312			{Dataset: "z", Distance: 1, Path: []string{"z", "report"}},
1313			{Dataset: "a", Distance: 2, Path: []string{"a", "z", "report"}},
1314			{Dataset: "b", Distance: 2, Path: []string{"b", "c", "report"}},
1315			{Dataset: "source", Distance: 3, Path: []string{"source", "a", "z", "report"}},
1316		}
1317	
1318		for i, seq := range sequences {
1319			graph := buildRegisteredGraph(t, seq)
1320			assertConsistent(t, graph)
1321			before := snapshot(graph)
1322	
1323			upstreams := mustUpstreams(t, graph, "report")
1324			if !reflect.DeepEqual(upstreams, want) {
1325				t.Fatalf("sequence %d: upstreams = %v, want %v", i, upstreams, want)
1326			}
1327	
1328			// Anchor with an explicit message: the shared source is explained
1329			// through a/z even though c sorts ahead of z.
1330			assertUpstreamOnce(t, upstreams, "source", 3, []string{"source", "a", "z", "report"})
1331	
1332			// The target itself, its downstream, and an unconnected dataset never
1333			// appear.
1334			names := upstreamNames(upstreams)
1335			if slices.Contains(names, "report") || slices.Contains(names, "view") || slices.Contains(names, "isolated") {
1336				t.Fatalf("sequence %d: target, downstream or isolated dataset leaked into %v", i, names)
1337			}
1338	
1339			// The query changes no node, relationship or stored list order.
1340			if !reflect.DeepEqual(snapshot(graph), before) {
1341				t.Fatalf("sequence %d: query changed graph: before=%v after=%v", i, before, snapshot(graph))
1342			}
1343		}
1344	}
