// A query never mutates the graph, and mutating the returned list or paths
// cannot reach back into the graph, into other records, or into later queries.
func TestUpstreamsReadOnlyAndIsolated(t *testing.T) {
	graph := map[string]*Lineage{}
	mustRegister(t, graph, "raw")
	mustRegister(t, graph, "a", "raw")
	mustRegister(t, graph, "b", "raw")
	mustRegister(t, graph, "report", "a", "b")
	before := snapshot(graph)

	upstreams, err := Upstreams(graph, "report")
	if err != nil {
		t.Fatalf("Upstreams(report): %v", err)
	}
	if !reflect.DeepEqual(snapshot(graph), before) {
		t.Fatalf("query changed graph: before=%v after=%v", before, snapshot(graph))
	}

	// Abuse the returned slices, then confirm the graph and a repeated query
	// are both untouched.
	upstreams[0].Path[0] = "tampered"
	upstreams[0].Path = append(upstreams[0].Path, "extra")
	upstreams[0].Dataset = "tampered"
	upstreams[0].Distance = 99
	if !reflect.DeepEqual(snapshot(graph), before) {
		t.Fatalf("mutating results changed graph: before=%v after=%v", before, snapshot(graph))
	}
	fresh := mustUpstreams(t, graph, "report")
	assertUpstream(t, fresh, "raw", 2, []string{"raw", "a", "report"})

	// A failed query is also read-only.
	if _, err := Upstreams(graph, "missing"); err == nil {
		t.Fatal("expected not-found error")
	}
	if !reflect.DeepEqual(snapshot(graph), before) {
		t.Fatalf("failed query changed graph: before=%v after=%v", before, snapshot(graph))
	}
	assertConsistent(t, graph)
}

// After report's direct upstreams are replaced by a same-name Register, a new
// query reflects the current edges, while the previously returned result keeps
// its original content.
func TestUpstreamsReflectReregisterAndOldResultStable(t *testing.T) {
	graph := map[string]*Lineage{}
	mustRegister(t, graph, "raw")
	mustRegister(t, graph, "a", "raw")
	mustRegister(t, graph, "b", "raw")
	mustRegister(t, graph, "report", "a", "b")

	before, err := Upstreams(graph, "report")
	if err != nil {
		t.Fatalf("Upstreams(report): %v", err)
	}
	assertUpstreamOnce(t, before, "raw", 2, []string{"raw", "a", "report"})
	beforeCopy := make([]Upstream, len(before))
	for i, up := range before {
		beforeCopy[i] = Upstream{up.Dataset, up.Distance, append([]string(nil), up.Path...)}
	}

	// report now depends on b only: a leaves its upstream set entirely, raw
	// remains reachable through b at distance 2 via the surviving route.
	mustRegister(t, graph, "report", "b")

	after, err := Upstreams(graph, "report")
	if err != nil {
		t.Fatalf("Upstreams(report) after re-register: %v", err)
	}
	if got, want := upstreamNames(after), []string{"b", "raw"}; !reflect.DeepEqual(got, want) {
		t.Fatalf("upstream order = %v, want %v", got, want)
	}
	assertUpstreamOnce(t, after, "b", 1, []string{"b", "report"})
	assertUpstreamOnce(t, after, "raw", 2, []string{"raw", "b", "report"})

	if !reflect.DeepEqual(before, beforeCopy) {
		t.Fatalf("earlier result changed after re-register/new query: before=%v snapshot=%v", before, beforeCopy)
	}
}

// Regression for replacing a middle dataset's direct upstreams so that the
// shortest route from a source to the report is deleted while a longer route
// keeps the source involved. raw feeds a and b; a feeds z; b feeds c; middle
// depends on raw, z and c together; report depends on middle. Initially raw
// reaches report at distance 2 via raw -> middle -> report. Re-registering
// middle with only z and c deletes that direct edge, but raw still derives
// report through raw -> a -> z -> middle -> report and raw -> b -> c -> middle
// -> report, both of length 4: raw must stay listed exactly once, at distance
// 4, and must not keep the stale distance-2 explanation. The two surviving
// routes have equal length, so the full path is compared name by name from the
// source: the paths first differ at hop 1 where a < b, hence the a/z route
// wins even though middle's direct upstream c sorts ahead of z. report's own
// direct dependency is untouched, so it still resolves every source through
// middle.
func TestUpstreamsAfterRewireLongerRouteSurvives(t *testing.T) {
	// Two builds of the same lineage with the independent branches registered
	// in opposite orders and middle's upstream list written differently; the
	// rewire likewise lists z and c in opposite orders. Identical final
	// relationships must give identical results.
	builds := []struct {
		registrations [][]string
		newParents    []string
	}{
		{
			registrations: [][]string{
				{"raw"},
				{"a", "raw"},
				{"z", "a"},
				{"b", "raw"},
				{"c", "b"},
				{"middle", "raw", "z", "c"},
				{"report", "middle"},
			},
			newParents: []string{"z", "c"},
		},
		{
			registrations: [][]string{
				{"raw"},
				{"b", "raw"}, // b-side branch registered first
				{"c", "b"},
				{"a", "raw"},
				{"z", "a"},
				{"middle", "c", "z", "raw"}, // upstream list order flipped
				{"report", "middle"},
			},
			newParents: []string{"c", "z"},
		},
	}

	wantBefore := []Upstream{
		{Dataset: "middle", Distance: 1, Path: []string{"middle", "report"}},
		{Dataset: "c", Distance: 2, Path: []string{"c", "middle", "report"}},
		{Dataset: "raw", Distance: 2, Path: []string{"raw", "middle", "report"}},
		{Dataset: "z", Distance: 2, Path: []string{"z", "middle", "report"}},
		{Dataset: "a", Distance: 3, Path: []string{"a", "z", "middle", "report"}},
		{Dataset: "b", Distance: 3, Path: []string{"b", "c", "middle", "report"}},
	}
	wantAfter := []Upstream{
		{Dataset: "middle", Distance: 1, Path: []string{"middle", "report"}},
		{Dataset: "c", Distance: 2, Path: []string{"c", "middle", "report"}},
		{Dataset: "z", Distance: 2, Path: []string{"z", "middle", "report"}},
		{Dataset: "a", Distance: 3, Path: []string{"a", "z", "middle", "report"}},
		{Dataset: "b", Distance: 3, Path: []string{"b", "c", "middle", "report"}},
		{Dataset: "raw", Distance: 4, Path: []string{"raw", "a", "z", "middle", "report"}},
	}

	for i, build := range builds {
		graph := buildRegisteredGraph(t, build.registrations)
		assertConsistent(t, graph)

		before := mustUpstreams(t, graph, "report")
		if !reflect.DeepEqual(before, wantBefore) {
			t.Fatalf("build %d: upstreams before rewire = %v, want %v", i, before, wantBefore)
		}
		// Anchor: the direct raw -> middle edge makes raw a distance-2 source.
		assertUpstreamOnce(t, before, "raw", 2, []string{"raw", "middle", "report"})
		beforeCopy := make([]Upstream, len(before))
		for j, up := range before {
			beforeCopy[j] = Upstream{up.Dataset, up.Distance, append([]string(nil), up.Path...)}
		}

		// Replace middle's direct upstreams, dropping the raw -> middle edge.
		// report's own direct dependency is not part of the request.
		mustRegister(t, graph, "middle", build.newParents...)
		assertConsistent(t, graph)
		assertEntry(t, graph, "middle", build.newParents, []string{"report"})
		assertEntry(t, graph, "report", []string{"middle"}, nil)
		graphBeforeQuery := snapshot(graph)

		after := mustUpstreams(t, graph, "report")
		if !reflect.DeepEqual(after, wantAfter) {
			t.Fatalf("build %d: upstreams after rewire = %v, want %v", i, after, wantAfter)
		}
		// Anchors with explicit messages: raw survives exactly once at the
		// longer distance, explained from the source hop by hop (a < b decides
		// at hop 1; middle's direct upstreams c < z must not decide it), and
		// the stale distance-2 route is gone.
		assertUpstreamOnce(t, after, "raw", 4, []string{"raw", "a", "z", "middle", "report"})
		assertUpstreamOnce(t, after, "middle", 1, []string{"middle", "report"})

		// The target never lists itself.
		if names := upstreamNames(after); slices.Contains(names, "report") {
			t.Fatalf("build %d: target leaked into its own upstreams %v", i, names)
		}

		// The query changed no node, relationship or stored list order.
		if !reflect.DeepEqual(snapshot(graph), graphBeforeQuery) {
			t.Fatalf("build %d: query changed graph: before=%v after=%v", i, graphBeforeQuery, snapshot(graph))
		}

		// The result obtained before the rewire kept its original content.
		if !reflect.DeepEqual(before, beforeCopy) {
			t.Fatalf("build %d: earlier result changed after re-register/new query: before=%v snapshot=%v",
				i, before, beforeCopy)
		}
	}
}

// Regression for detaching a middle dataset from ALL of its direct upstreams
// by re-registering it with an empty upstream list, where the report still has
// a second branch reaching back to the old source. raw derives a and z; middle
// depends on raw and a; report depends on middle and z. Before the detach, raw
// reaches report over two shortest routes of length 2 (raw -> middle -> report
// and raw -> z -> report), and the lexicographically smaller middle route is
// the explanation. Detaching middle makes it a new root without deleting it or
// breaking its downstream edge to report: middle stays a distance-1 source, a
// leaves report's sources entirely, but raw survives exactly once at distance
// 2 through the remaining z branch, with the explanation re-derived as
// raw -> z -> report instead of the removed middle route.
func TestUpstreamsAfterDetachAllUpstreamsSecondBranchSurvives(t *testing.T) {
	graph := buildRegisteredGraph(t, [][]string{
		{"raw"},
		{"a", "raw"},
		{"z", "raw"},
		{"middle", "raw", "a"},
		{"report", "middle", "z"},
	})
	assertConsistent(t, graph)

	wantBefore := []Upstream{
		{Dataset: "middle", Distance: 1, Path: []string{"middle", "report"}},
		{Dataset: "z", Distance: 1, Path: []string{"z", "report"}},
		{Dataset: "a", Distance: 2, Path: []string{"a", "middle", "report"}},
		{Dataset: "raw", Distance: 2, Path: []string{"raw", "middle", "report"}},
	}
	before := mustUpstreams(t, graph, "report")
	if !reflect.DeepEqual(before, wantBefore) {
		t.Fatalf("upstreams before detach = %v, want %v", before, wantBefore)
	}
	// Anchor: of the two length-2 routes from raw, the middle route explains.
	assertUpstreamOnce(t, before, "raw", 2, []string{"raw", "middle", "report"})
	beforeCopy := make([]Upstream, len(before))
	for i, up := range before {
		beforeCopy[i] = Upstream{up.Dataset, up.Distance, append([]string(nil), up.Path...)}
	}

	// Detach middle from every direct upstream. report's own direct
	// dependencies are not part of the request and must not change.
	mustRegister(t, graph, "middle")
	assertConsistent(t, graph)
	assertEntry(t, graph, "middle", nil, []string{"report"})
	assertEntry(t, graph, "report", []string{"middle", "z"}, nil)
	assertEntry(t, graph, "raw", nil, []string{"a", "z"})
	assertEntry(t, graph, "a", []string{"raw"}, nil)
	assertEntry(t, graph, "z", []string{"raw"}, []string{"report"})
	graphBeforeQuery := snapshot(graph)

	wantAfter := []Upstream{
		{Dataset: "middle", Distance: 1, Path: []string{"middle", "report"}},
		{Dataset: "z", Distance: 1, Path: []string{"z", "report"}},
		{Dataset: "raw", Distance: 2, Path: []string{"raw", "z", "report"}},
	}
	after := mustUpstreams(t, graph, "report")
	if !reflect.DeepEqual(after, wantAfter) {
		t.Fatalf("upstreams after detach = %v, want %v", after, wantAfter)
	}
	// Anchors with explicit messages: middle stays a direct source, a is gone,
	// and raw survives exactly once via z — it must not follow a out of the
	// result, nor keep the detached raw -> middle -> report explanation.
	assertUpstreamOnce(t, after, "middle", 1, []string{"middle", "report"})
	assertUpstreamOnce(t, after, "raw", 2, []string{"raw", "z", "report"})
	if names := upstreamNames(after); slices.Contains(names, "a") || slices.Contains(names, "report") {
		t.Fatalf("detached upstream or target leaked into %v", names)
	}

	// The query is read-only and does not resurrect middle's detached
	// upstreams.
	if !reflect.DeepEqual(snapshot(graph), graphBeforeQuery) {
		t.Fatalf("query changed graph: before=%v after=%v", graphBeforeQuery, snapshot(graph))
	}
	assertEntry(t, graph, "middle", nil, []string{"report"})

	// The result obtained before the detach kept its original content.
	if !reflect.DeepEqual(before, beforeCopy) {
		t.Fatalf("earlier result changed after detach/new query: before=%v snapshot=%v", before, beforeCopy)
	}
}

// Regression for detaching a middle dataset from ALL of its direct upstreams
// where the report has no second branch back to the old sources. raw derives
// a; middle depends on raw and a; report depends on middle alone. After the

package chainledger

import (
	"bytes"
	"reflect"
	"slices"
	"strconv"
	"strings"
	"testing"
)

// reregisterBadSource is a registered source whose name carries a REAL lone
// 0xff byte — invalid UTF-8 — not the four printable characters backslash, x,
// f, f. Such a name still registers; only an export of a closure that contains
// it must reject the document.
const reregisterBadSource = "source\xff"

// exportReregisterEncodingScenario builds the multi-branch lineage for the
// replacement regression:
//
//	source\xff ──> alpha ──┐
//	source\xff ──> beta  ──┼──> merge ──> target
//	clean ────────────────┘
//
// The invalid source participates in merge's derivation through TWO different
// intermediate datasets (alpha and beta), and merge also depends directly on
// the legal source clean. target depends solely on merge. The bad source's
// name is the only invalid name in target's closure.
func exportReregisterEncodingScenario(t *testing.T) map[string]*Lineage {
	t.Helper()
	// Self-check the fixture: 0xff must be an actual byte of the name rather
	// than literal "\xff" text, otherwise this regression would test nothing.
	if !bytes.Contains([]byte(reregisterBadSource), []byte{0xff}) ||
		strings.Contains(reregisterBadSource, `\xff`) {
		t.Fatalf("fixture constant must hold a real 0xff byte, got %q", reregisterBadSource)
	}
	return buildRegisteredGraph(t, [][]string{
		{reregisterBadSource},
		{"clean"},
		{"alpha", reregisterBadSource}, // first branch through which the bad source derives merge
		{"beta", reregisterBadSource},  // second, independent branch
		{"merge", "alpha", "beta", "clean"},
		{"target", "merge"},
	})
}

// reregisterEncodingError is the one encoding failure every blocked phase must
// report: the offending name in Go-quoted form, with the bad byte kept as its
// own \xNN escape.
func reregisterEncodingError(t *testing.T, graph map[string]*Lineage, target string) string {
	t.Helper()
	out, err := ExportUpstreamLineage(graph, target)
	if err == nil {
		t.Fatalf("ExportUpstreamLineage(%q) with invalid source %q in its lineage succeeded: %s",
			target, reregisterBadSource, out)
	}
	if out != "" {
		t.Errorf("ExportUpstreamLineage(%q) returned partial content %q, want empty string", target, out)
	}
	if !strings.Contains(err.Error(), "not valid UTF-8") {
		t.Errorf("ExportUpstreamLineage(%q) error %q must be the encoding error", target, err)
	}
	quoted := strconv.Quote(reregisterBadSource) // "source\xff" — the escape, not the byte
	if !strings.Contains(err.Error(), quoted) {
		t.Errorf("ExportUpstreamLineage(%q) error %q must preserve the bad byte in Go-quoted form %s",
			target, err, quoted)
	}
	if !strings.Contains(err.Error(), `\xff`) {
		t.Errorf("ExportUpstreamLineage(%q) error %q must show the 0xff byte as \\xff", target, err)
	}
	return err.Error()
}

// Full replacement regression around same-name Register calls on the merge
// dataset while one of its ancestor sources carries an invalid-UTF-8 name.
//
// The export verdict must be derived solely from the sources target CURRENTLY
// depends on — every surviving branch counts, and neither a branch removed from
// the direct-upstream list nor the history of having participated can change
// the answer. The bad name blocks while either route survives; only when the
// last bad route is severed does export succeed. Exited sources and
// intermediates stay registered throughout — no delete or rename is used to
// repair.
func TestExportUpstreamLineageReregisterReplaceUpstreamsEncoding(t *testing.T) {
	graph := exportReregisterEncodingScenario(t)
	assertConsistent(t, graph)

	// The invalid name registered normally and answers normally from the
	// registry-side queries, raw byte and all; encoding is a rule of the
	// export alone.
	if _, ok := graph[reregisterBadSource]; !ok {
		t.Fatal("source with the 0xff byte must be registered")
	}
	if got, want := upstreamNames(mustUpstreams(t, graph, "target")),
		[]string{"merge", "alpha", "beta", "clean", reregisterBadSource}; !reflect.DeepEqual(got, want) {
		t.Fatalf("upstreams before replacement = %q, want %q", got, want)
	}

	// Phase A: both bad branches live. Exporting target (indirect dependency)
	// and merge (direct dependency through alpha/beta) fails wholesale: empty
	// string, no partial JSON, the bad byte shown escaped.
	phaseA := snapshotExportGraph(graph)
	errA := reregisterEncodingError(t, graph, "target")
	reregisterEncodingError(t, graph, "merge")
	assertGraphUnchanged(t, phaseA, graph)
	assertEntry(t, graph, "merge", []string{"alpha", "beta", "clean"}, []string{"target"})
	assertEntry(t, graph, reregisterBadSource, nil, []string{"alpha", "beta"})

	// Phase B: replace merge's direct upstreams wholesale, severing only the
	// route through alpha. The beta route and the legal clean source remain.
	mustRegister(t, graph, "merge", "beta", "clean")
	assertConsistent(t, graph)
	assertEntry(t, graph, "merge", []string{"beta", "clean"}, []string{"target"})
	// alpha detached from merge but still registered and still derived from
	// the bad source; the reverse edge into merge is gone from alpha, while
	// beta kept exactly its slot.
	assertEntry(t, graph, "alpha", []string{reregisterBadSource}, nil)
	assertEntry(t, graph, "beta", []string{reregisterBadSource}, []string{"merge"})
	assertEntry(t, graph, "clean", nil, []string{"merge"})
	assertEntry(t, graph, reregisterBadSource, nil, []string{"alpha", "beta"})

	// target still reaches the bad name indirectly along merge -> beta. One
	// fewer dependency edge must not repair the export; the failure is the
	// very same encoding error, and nothing about the registry moves.
	if got, want := upstreamNames(mustUpstreams(t, graph, "target")),
		[]string{"merge", "beta", "clean", reregisterBadSource}; !reflect.DeepEqual(got, want) {
		t.Fatalf("upstreams after severing one branch = %q, want %q", got, want)
	}
	phaseB := snapshotExportGraph(graph)
	errB := reregisterEncodingError(t, graph, "target")
	if errB != errA {
		t.Errorf("severing one bad route changed the encoding error:\nbefore: %q\nafter:  %q", errA, errB)
	}
	assertGraphUnchanged(t, phaseB, graph)

	// A replacement that names an unregistered upstream is rejected naming
	// that upstream, and validation happens before any edge is touched: merge
	// keeps its phase-B parents and children in order, and every neighbor list
	// is untouched.
	err := Register(graph, Dataset{Name: "merge"}, []string{"clean", "ghost"})
	if err == nil || !strings.Contains(err.Error(), "unknown parent") ||
		!strings.Contains(err.Error(), "ghost") {
		t.Fatalf("want unknown-parent error naming ghost, got %v", err)
	}
	assertGraphUnchanged(t, phaseB, graph)
	assertEntry(t, graph, "merge", []string{"beta", "clean"}, []string{"target"})
	assertEntry(t, graph, "beta", []string{reregisterBadSource}, []string{"merge"})
	assertEntry(t, graph, "alpha", []string{reregisterBadSource}, nil)
	assertConsistent(t, graph)

	// With the rejected replacement leaving the surviving beta route in place,
	// the export still reports the original encoding problem, not success and
	// not the registration error.
	errC := reregisterEncodingError(t, graph, "target")
	if errC != errA {
		t.Errorf("export after a rejected replacement reported a different error:\nwant: %q\ngot:  %q",
			errA, errC)
	}
	assertGraphUnchanged(t, phaseB, graph)

	// Phase C: replace merge's direct upstreams with the legal source alone.
	// The LAST route through the invalid source is severed; beta drops its
	// reverse edge to merge.
	mustRegister(t, graph, "merge", "clean")
	assertConsistent(t, graph)
	assertEntry(t, graph, "merge", []string{"clean"}, []string{"target"})
	assertEntry(t, graph, "clean", nil, []string{"merge"})
	assertEntry(t, graph, "beta", []string{reregisterBadSource}, nil)
	// The bad source and both intermediates remain registered, still linked to
	// one another outside target's lineage. Repair came from replacing the
	// direct-upstream list, never from deleting or renaming anything.
	assertEntry(t, graph, "alpha", []string{reregisterBadSource}, nil)
	assertEntry(t, graph, reregisterBadSource, nil, []string{"alpha", "beta"})
	if len(graph) != 6 {
		t.Errorf("dataset count = %d, want 6 (exited lineage nodes stay registered)", len(graph))
	}

	// target now depends only on merge and clean: the historical participation
	// of source\xff through either branch is no longer a basis for the verdict.
	if got, want := upstreamNames(mustUpstreams(t, graph, "target")),
		[]string{"merge", "clean"}; !reflect.DeepEqual(got, want) {
		t.Fatalf("upstreams after severing the last branch = %q, want %q", got, want)
	}
	phaseC := snapshotExportGraph(graph)
	out := mustExport(t, graph, "target")
	wantText := `{"nodes":["clean","merge","target"],` +
		`"edges":[{"from":"clean","to":"merge"},{"from":"merge","to":"target"}]}`
	if out != wantText {
		t.Errorf("export after severing the last bad route =\n%s\nwant:\n%s", out, wantText)
	}
	doc := parseExport(t, out)
	if !reflect.DeepEqual(doc.Nodes, []string{"clean", "merge", "target"}) {
		t.Errorf("nodes = %q, want only target, merge and the surviving legal source", doc.Nodes)
	}
	if got := exportEdgeNames(doc); !reflect.DeepEqual(got, [][2]string{
		{"clean", "merge"},
		{"merge", "target"},
	}) {
		t.Errorf("edges = %q, want only the surviving direct dependencies", got)
	}
	if bytes.Contains([]byte(out), []byte{0xff}) {
		t.Errorf("illegal byte leaked into the successful export: %s", out)
	}
	for _, excluded := range []string{"alpha", "beta", reregisterBadSource} {
		if slices.Contains(doc.Nodes, excluded) {
			t.Errorf("node %q that left target's lineage must not be exported: %q", excluded, doc.Nodes)
		}
	}
	// Same lineage relationships, had they always been clean, produce
	// byte-identical output: the removed routes leave no trace beyond their
	// surviving registrations elsewhere in the graph.
	twin := buildRegisteredGraph(t, [][]string{
		{"clean"},
		{"merge", "clean"},
		{"target", "merge"},
	})
	if twinOut := mustExport(t, twin, "target"); twinOut != out {
		t.Errorf("repaired export differs from an always-clean twin:\nrepaired: %s\ntwin:     %s",
			out, twinOut)
	}
	// A successful export is read-only too: every registration and list order
	// stays exactly as after the replacement.
	assertGraphUnchanged(t, phaseC, graph)
}

// Severing EITHER one of the two bad branches alone leaves the other route and
// therefore leaves the encoding failure in place; branch identity, replacement
// list order and the legal source's presence cannot make one-route removal
// sufficient. Both routes must be gone before target exports.
func TestExportUpstreamLineageReregisterOneBranchRemovalNeverSuffices(t *testing.T) {
	cases := []struct {
		name        string
		keepParents []string // merge's replacement direct upstreams, one bad branch kept
	}{
		{"keep beta route", []string{"beta", "clean"}},
		{"keep alpha route", []string{"clean", "alpha"}}, // legal source listed first this time
		{"keep alpha only", []string{"alpha"}},           // legal source dropped as well
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			graph := exportReregisterEncodingScenario(t)
			errBefore := reregisterEncodingError(t, graph, "target")

			mustRegister(t, graph, "merge", tc.keepParents...)
			assertConsistent(t, graph)
			// The bad source still feeds a kept intermediate, which still feeds
			// merge: target's current closure contains the invalid name.
			if !slices.Contains(upstreamNames(mustUpstreams(t, graph, "target")), reregisterBadSource) {
				t.Fatalf("bad source must still be an upstream of target with parents %v", tc.keepParents)
			}
			errAfter := reregisterEncodingError(t, graph, "target")
			if errAfter != errBefore {
				t.Errorf("encoding error changed after partial branch removal:\nbefore: %q\nafter:  %q",
					errBefore, errAfter)
			}

			// Removing the final kept route repairs the export without touching
			// any registration; clean alone has a valid name.
			mustRegister(t, graph, "merge", "clean")
			if slices.Contains(upstreamNames(mustUpstreams(t, graph, "target")), reregisterBadSource) {
				t.Fatal("bad source must stop being an upstream once merge keeps only clean")
			}
			repaired := snapshotExportGraph(graph)
			out := mustExport(t, graph, "target")
			if want := `{"nodes":["clean","merge","target"],` +
				`"edges":[{"from":"clean","to":"merge"},{"from":"merge","to":"target"}]}`; out != want {
				t.Errorf("export =\n%s\nwant:\n%s", out, want)
			}
			if bytes.Contains([]byte(out), []byte{0xff}) {
				t.Errorf("illegal byte leaked into the export: %s", out)
			}
			// The intermediates and bad source detached by the replacements are
			// still registered, still mutually linked.
			assertEntry(t, graph, reregisterBadSource, nil, []string{"alpha", "beta"})
			assertEntry(t, graph, "alpha", []string{reregisterBadSource}, nil)
			assertEntry(t, graph, "beta", []string{reregisterBadSource}, nil)
			// The successful export was read-only over the repaired registry.
			assertGraphUnchanged(t, repaired, graph)
		})
	}
}

package chainledger

import (
	"reflect"
	"strings"
	"testing"
)

// Regression for reusing a freed name as an independent registration after a
// rename, then pointing the renamed dataset at it. raw feeds mid; mid feeds
// detail; detail feeds report; raw also feeds the unrelated side. Renaming mid
// to hub frees the name mid, which is then registered as a new source with no
// upstreams and given its own downstream midchild first. Re-registering hub
// with mid as its only direct upstream must succeed: mid and hub are two
// independent registrations, hub keeps its original downstream chain, raw
// drops hub from its children but keeps side, and hub lands at the end of
// mid's child list behind midchild. Afterwards raw's impact scope is just
// side, while mid reaches hub, detail and report at distances 1, 2 and 3, and
// report's provenance runs detail <- hub <- mid with raw gone.
func TestRenameThenReuseFreedNameAsUpstream(t *testing.T) {
	graph := buildRegisteredGraph(t, [][]string{
		{"raw"},
		{"mid", "raw"},
		{"detail", "mid"},
		{"report", "detail"},
		{"side", "raw"}, // unrelated downstream of raw
	})
	assertConsistent(t, graph)

	// Rename the middle dataset: the name mid is freed, the node keeps its
	// exact position, and every neighbor reference is rewired in place.
	mustRename(t, graph, "mid", "hub")
	assertConsistent(t, graph)
	assertEntry(t, graph, "raw", nil, []string{"hub", "side"})
	assertEntry(t, graph, "hub", []string{"raw"}, []string{"detail"})
	assertEntry(t, graph, "detail", []string{"hub"}, []string{"report"})
	assertEntry(t, graph, "report", []string{"detail"}, nil)
	assertEntry(t, graph, "side", []string{"raw"}, nil)

	// While mid is still unregistered it cannot be hub's upstream: the error
	// names mid, and the rejection is atomic.
	beforeRejected := snapshot(graph)
	rawImpactsBeforeRejected := mustImpacts(t, graph, "raw")
	err := Register(graph, Dataset{Name: "hub"}, []string{"mid"})
	if err == nil || !strings.Contains(err.Error(), "unknown parent") || !strings.Contains(err.Error(), "mid") {
		t.Fatalf("want unknown-parent error naming mid, got %v", err)
	}
	if !reflect.DeepEqual(snapshot(graph), beforeRejected) {
		t.Fatalf("rejected registration changed graph: before=%v after=%v", beforeRejected, snapshot(graph))
	}
	assertEntry(t, graph, "hub", []string{"raw"}, []string{"detail"})
	assertEntry(t, graph, "raw", nil, []string{"hub", "side"})
	if got := mustImpacts(t, graph, "raw"); !reflect.DeepEqual(got, rawImpactsBeforeRejected) {
		t.Fatalf("impacts after rejected registration = %v, want %v", got, rawImpactsBeforeRejected)
	}
	assertConsistent(t, graph)

	// Register mid as a brand-new source with no upstreams, and let it own
	// another downstream first. It is an independent registration, unrelated
	// to the renamed hub.
	mustRegister(t, graph, "mid")
	mustRegister(t, graph, "midchild", "mid")
	assertConsistent(t, graph)
	assertEntry(t, graph, "mid", nil, []string{"midchild"})
	assertEntry(t, graph, "midchild", []string{"mid"}, nil)

	// Mixing the legitimate new source with hub's own downstream report must
	// be refused as a whole: report reaches hub through detail, so the edge
	// hub -> report would close a cycle. The error names report and the cycle,
	// and the valid mid listed first must not have changed anything.
	beforeCycle := snapshot(graph)
	rawImpactsBeforeCycle := mustImpacts(t, graph, "raw")
	reportUpstreamsBeforeCycle := mustUpstreams(t, graph, "report")
	err = Register(graph, Dataset{Name: "hub"}, []string{"mid", "report"})
	if err == nil || !strings.Contains(err.Error(), "cycle") || !strings.Contains(err.Error(), "report") {
		t.Fatalf("want cycle error naming report, got %v", err)
	}
	if !reflect.DeepEqual(snapshot(graph), beforeCycle) {
		t.Fatalf("rejected cyclic registration changed graph: before=%v after=%v", beforeCycle, snapshot(graph))
	}
	assertEntry(t, graph, "hub", []string{"raw"}, []string{"detail"})
	assertEntry(t, graph, "mid", nil, []string{"midchild"})
	assertEntry(t, graph, "raw", nil, []string{"hub", "side"})
	if got := mustImpacts(t, graph, "raw"); !reflect.DeepEqual(got, rawImpactsBeforeCycle) {
		t.Fatalf("impacts after rejected cyclic registration = %v, want %v", got, rawImpactsBeforeCycle)
	}
	if got := mustUpstreams(t, graph, "report"); !reflect.DeepEqual(got, reportUpstreamsBeforeCycle) {
		t.Fatalf("report upstreams after rejected cyclic registration = %v, want %v", got, reportUpstreamsBeforeCycle)
	}
	assertConsistent(t, graph)

	// Replace hub's direct upstreams wholesale with the reused name mid. This
	// must succeed: mid and hub are independent registrations, and the edge
	// mid -> hub closes no cycle.
	mustRegister(t, graph, "hub", "mid")
	assertConsistent(t, graph)

	// The graph now holds two independent registrations under the old and new
	// names. raw released hub but keeps its unrelated downstream side; mid
	// keeps its own downstream midchild and gains hub appended at the end;
	// hub keeps its original downstream chain untouched.
	if got, want := len(graph), 7; got != want {
		t.Fatalf("dataset count = %d, want %d", got, want)
	}
	assertEntry(t, graph, "raw", nil, []string{"side"})
	assertEntry(t, graph, "mid", nil, []string{"midchild", "hub"})
	assertEntry(t, graph, "hub", []string{"mid"}, []string{"detail"})
	assertEntry(t, graph, "detail", []string{"hub"}, []string{"report"})
	assertEntry(t, graph, "report", []string{"detail"}, nil)
	assertEntry(t, graph, "midchild", []string{"mid"}, nil)
	assertEntry(t, graph, "side", []string{"raw"}, nil)

	// From raw the whole moved chain is gone; only the unrelated side remains.
	wantRawImpacts := []Impact{
		{Dataset: "side", Distance: 1, Path: []string{"raw", "side"}},
	}
	rawImpacts := mustImpacts(t, graph, "raw")
	if !reflect.DeepEqual(rawImpacts, wantRawImpacts) {
		t.Fatalf("impacts from raw = %v, want %v", rawImpacts, wantRawImpacts)
	}

	// From mid the chain unfolds along mid -> hub -> detail -> report at
	// distances 1, 2 and 3, with midchild as mid's other direct downstream.
	wantMidImpacts := []Impact{
		{Dataset: "hub", Distance: 1, Path: []string{"mid", "hub"}},
		{Dataset: "midchild", Distance: 1, Path: []string{"mid", "midchild"}},
		{Dataset: "detail", Distance: 2, Path: []string{"mid", "hub", "detail"}},
		{Dataset: "report", Distance: 3, Path: []string{"mid", "hub", "detail", "report"}},
	}
	midImpacts := mustImpacts(t, graph, "mid")
	if !reflect.DeepEqual(midImpacts, wantMidImpacts) {
		t.Fatalf("impacts from mid = %v, want %v", midImpacts, wantMidImpacts)
	}
	assertImpactOnce(t, midImpacts, "hub", 1, []string{"mid", "hub"})
	assertImpactOnce(t, midImpacts, "detail", 2, []string{"mid", "hub", "detail"})
	assertImpactOnce(t, midImpacts, "report", 3, []string{"mid", "hub", "detail", "report"})

	// Tracing report's provenance walks detail, hub, mid in order; raw is no
	// longer a source of report. Paths are written along the actual
	// derivation direction, from each source toward report.
	wantReportUpstreams := []Upstream{
		{Dataset: "detail", Distance: 1, Path: []string{"detail", "report"}},
		{Dataset: "hub", Distance: 2, Path: []string{"hub", "detail", "report"}},
		{Dataset: "mid", Distance: 3, Path: []string{"mid", "hub", "detail", "report"}},
	}
	reportUpstreams := mustUpstreams(t, graph, "report")
	if !reflect.DeepEqual(reportUpstreams, wantReportUpstreams) {
		t.Fatalf("upstreams of report = %v, want %v", reportUpstreams, wantReportUpstreams)
	}
	assertUpstreamOnce(t, reportUpstreams, "mid", 3, []string{"mid", "hub", "detail", "report"})
	for _, up := range reportUpstreams {
		if up.Dataset == "raw" {
			t.Fatalf("raw leaked into report upstreams after replacement: %v", reportUpstreams)
		}
	}
}

